"use client";
import { useMemo, useState } from "react";
const products=[{name:"Coca-Cola",price:1500,stock:10},{name:"Bread",price:2250,stock:11},{name:"Rice 5kg",price:3000,stock:12},{name:"Milk",price:3750,stock:13},{name:"Biscuits",price:4500,stock:14},{name:"Water",price:5250,stock:0}];
export default function ItemsPage(){const [q,setQ]=useState("");const filtered=useMemo(()=>products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())),[q]);return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-6xl"><header className="mb-7"><p className="text-xl font-bold">TX <span className="text-orange-500">RetailOS</span></p><h1 className="mt-5 text-2xl font-semibold">Products</h1></header><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search products by name..." className="mb-6 w-full rounded-xl border border-white/10 bg-[#151515] px-4 py-3 text-sm outline-none focus:border-orange-500"/><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{filtered.map(p=><article key={p.name} className="rounded-2xl border border-white/10 bg-[#151515] p-5"><div className="mb-5 h-28 rounded-xl bg-white/5"/><h2 className="font-semibold">{p.name}</h2><p className="mt-1 text-xs text-white/40">Uncategorised</p><div className="mt-5 grid grid-cols-2 gap-3"><div><p className="text-xs text-white/40">Price</p><p className="mt-1 font-medium">₦{p.price.toLocaleString()}</p></div><div><p className="text-xs text-white/40">Stock</p><p className="mt-1 font-medium">{p.stock} units</p></div></div></article>)}</div></div></main>}
